import{d as s,C as n,o as g,c as h,E as i,a3 as a}from"./chunks/framework.Q4yG9rk_.js";const b=JSON.parse('{"title":"升卦","description":"第四十六卦·地风升——地中生木，积小以高大。升不是用力往上冲，是顺着该顺的势，一层一层地长上去。","frontmatter":{"title":"升卦","description":"第四十六卦·地风升——地中生木，积小以高大。升不是用力往上冲，是顺着该顺的势，一层一层地长上去。","category":"hexagram","aliases":["升","地风升"],"source":["《周易》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/hexagrams/46-difengsheng.md","filePath":"yijing/hexagrams/46-difengsheng.md","lastUpdated":1789987057000}'),p={name:"yijing/hexagrams/46-difengsheng.md"},x=s({...p,setup(u){const o=[{id:"yunsheng",term:"允升",pinyin:"yǔn shēng",meaning:"允即信从、诚然。为众人所信从而上升，故大吉。",context:"小象「上合志也」——升的起点是与上位者志同道合，不是孤身蛮力。"},{id:"fu",term:"孚",pinyin:"fú",meaning:"诚信、信实，指内核的真实。",context:"九二「孚乃利用禴」：内核真实，形式可简。"},{id:"yue",term:"禴",pinyin:"yuè",meaning:"薄祭、夏祭。祭礼从简，而心诚为先。"},{id:"xuyi",term:"虚邑",pinyin:"xū yì",meaning:"空城、无人防守的城邑，喻路径通畅无阻。",context:"小象「无所疑也」——不是刻意不疑，是专注到没有空间去犹豫。"},{id:"heng",term:"亨",pinyin:"hēng",meaning:"此处通「享」，指祭祀献享。",context:"六四「王用亨于岐山」，重在郑重献上的姿态。"},{id:"qishan",term:"岐山",pinyin:"qí shān",meaning:"周室发祥之地，文王在此祭天，喻与更大的系统对齐。",context:"小象「顺事也」。"},{id:"mingsheng",term:"冥升",pinyin:"míng shēng",meaning:"升至昏暗不明之处。",context:"小象「消不富也」——升到极致已是消耗，而非丰盈。"},{id:"buxizhizhen",term:"不息之贞",pinyin:"bù xī zhī zhēn",meaning:"持续不断的守正。不是想通了大道理，是继续做下去的动作本身。"},{id:"shunde",term:"顺德",pinyin:"shùn dé",meaning:"顺其德、顺时顺势之德。象传「君子以顺德」，是升卦的总纲。"}],e=[{position:"初六",type:"yin",text:"允升，大吉。",xiang:"允升大吉，上合志也。",textModern:"为众人所信从而上升，大为吉利。",xiangModern:"允升而大吉，因为与上位者志同道合。"},{position:"九二",type:"yang",text:"孚乃利用禴，无咎。",xiang:"九二之孚，有喜也。",textModern:"内心有真诚，即便祭礼简薄，也没有灾祸。",xiangModern:"九二这份诚信，是有喜事的。"},{position:"九三",type:"yang",text:"升虚邑。",xiang:"升虚邑，无所疑也。",textModern:"升入一座无人抵抗的空城，畅通无阻。",xiangModern:"升虚邑，是没有什么可疑虑的。"},{position:"六四",type:"yin",text:"王用亨于岐山，吉无咎。",xiang:"王用亨于岐山，顺事也。",textModern:"王在岐山郑重祭祀，吉祥且无灾祸。",xiangModern:"王在岐山祭祀，是顺于事理的。"},{position:"六五",type:"yin",text:"贞吉，升阶。",xiang:"贞吉升阶，大得志也。",textModern:"守正得吉，如同踏着台阶，一级一级稳步登临。",xiangModern:"守正得吉而拾级而上，是大得志。"},{position:"上六",type:"yin",text:"冥升，利于不息之贞。",xiang:"冥升在上，消不富也。",textModern:"升至昏暗不明之境，唯有持续不断地守正才有利。",xiangModern:"冥升于上位，是消耗而非丰盈。"}];return(m,t)=>{const r=n("DaoHexagramViewer"),l=n("DaoHexagramYaoCards"),d=n("DaoKeywordCards");return g(),h("div",null,[i(r,{name:"升",fullName:"地风升",upper:"☷",lower:"☴",guaCi:"升，元亨。用见大人，勿恤。南征吉。",pinyin:["shēng"],element:"木",direction:"东",insight:"地中生木，日渐生长，破土而出。升不是用力往上冲，是顺着该顺的势，一层一层地长上去。",guaSlug:"46difengsheng",lines:e}),t[0]||(t[0]=a('<h2 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to &quot;彖传&quot;">​</a></h2><p>柔以时升，巽而顺，刚中而应，是以大亨。用见大人勿恤，有庆也。南征吉，志行也。</p><p>逐句释义：</p><ul><li><strong>柔以时升</strong> —— 以柔顺应时势而升，不是硬冲。这一个「柔」字是升卦全篇的底色。</li><li><strong>巽而顺</strong> —— 下卦巽（入而顺），上卦坤（顺），内巽外顺，层层顺承。</li><li><strong>刚中而应</strong> —— 九二刚而居中，与六五相应；一刚一柔相与，故能大通。</li><li><strong>是以大亨</strong> —— 所以「元亨」。</li><li><strong>用见大人勿恤，有庆也</strong> —— 以此见大人，不必忧虑，自有喜庆。</li><li><strong>南征吉，志行也</strong> —— 向南进发吉利（离为南、为明），是因为志向得以施行。</li></ul><blockquote><p><strong>柔升哲学</strong>：升的动力不是蛮力，是「柔以时」——该长的时候长，该顺的时候顺。</p></blockquote><h2 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to &quot;象传&quot;">​</a></h2><p>地中生木，升。君子以顺德，积小以高大。</p><p>木在地中（坤上巽下，巽为木），日渐生长，破土而出——这是升之象。君子由此悟到：<strong>顺德，积小以高大</strong>。</p><p><strong>顺德</strong>是总纲：顺其德、顺时、顺势。<strong>积小以高大</strong>是它的自然结果——「积」不是功利手段，是顺势而为走出来的自然痕迹，像水往低处走、江海自然汇聚，而不是刻意堆砌的表演。</p><blockquote><p><strong>积小哲学</strong>：真正的积累不是堆高，是长高。堆出来的会塌，长出来的不会。</p></blockquote><h2 id="六爻" tabindex="-1">六爻 <a class="header-anchor" href="#六爻" aria-label="Permalink to &quot;六爻&quot;">​</a></h2>',11)),i(l,{element:"木",guaSlug:"46difengsheng",glossary:o,items:e}),t[1]||(t[1]=a('<h2 id="六爻详解" tabindex="-1">六爻详解 <a class="header-anchor" href="#六爻详解" aria-label="Permalink to &quot;六爻详解&quot;">​</a></h2><p>升卦的六爻，是一条「从找同伴，到在暗处依然不停」的线路：起点不靠孤身蛮力（初六），中段靠真实的内核立住（九二）、靠专注走出通途（九三），再以郑重的姿态与更大的系统对齐（六四），在柔顺谦冲里大得其志（六五），最后在看不清方向处仍不停止（上六）。</p><h3 id="初六-·-允升-大吉" tabindex="-1">初六 · 允升，大吉 <a class="header-anchor" href="#初六-·-允升-大吉" aria-label="Permalink to &quot;初六 · 允升，大吉&quot;">​</a></h3><ul><li>卦之初，柔顺在下的位置</li><li><strong>允升</strong>：为众人所信从而上升</li><li>小象「上合志也」：升的起点是与上位者志同道合</li></ul><p>升的起点，不是孤身蛮力向上，而是寻找志同道合的同盟。这里最需要核对的是：有没有沉溺于「孤行者」的悲情叙事？真正的升，从来不是一个人硬扛出来的。</p><blockquote><p>升的第一步，是抬头看见可以同行的人。</p></blockquote><h3 id="九二-·-孚乃利用禴-无咎" tabindex="-1">九二 · 孚乃利用禴，无咎 <a class="header-anchor" href="#九二-·-孚乃利用禴-无咎" aria-label="Permalink to &quot;九二 · 孚乃利用禴，无咎&quot;">​</a></h3><ul><li>阳爻居二位，刚而居中，与六五相应</li><li><strong>孚</strong>：内核的真实；<strong>禴</strong>：简薄的祭礼</li><li>小象「有喜也」</li></ul><p>排场是给别人看的，孚是给自己留的底。创业或表达的起步阶段，不需要用「隆重的成果」去交换认可——真实的内核足以撑起一切不完整。</p><p>但「怕麻烦省略细节」里藏着两种可能，需要分辨：</p><table tabindex="0"><thead><tr><th>可能</th><th>性质</th><th>判断标准</th></tr></thead><tbody><tr><td>理性的优先级排序（先跑通主线，精修留后）</td><td>清醒</td><td>是否清醒地知道「这里值得被认真对待，只是这一轮先放过」</td></tr><tr><td>用「糊弄也能过」回避「我做得到底行不行」的评判焦虑</td><td>需警惕</td><td>是否在回避评判，而不是在安排顺序</td></tr></tbody></table><blockquote><p>形式可简，内核不可省；简与糊的分界，全在你自己知不知道。</p></blockquote><h3 id="九三-·-升虚邑" tabindex="-1">九三 · 升虚邑 <a class="header-anchor" href="#九三-·-升虚邑" aria-label="Permalink to &quot;九三 · 升虚邑&quot;">​</a></h3><ul><li>下卦巽（风、木）的终点，紧邻上卦坤</li><li><strong>虚邑</strong>：空城，无人抵抗</li><li>小象「无所疑也」</li></ul><p>真正的「无所疑」不是刻意的克制，而是专注到没有空间去犹豫。路径通畅，因为「空」——没有车马喧嚣的诱惑，故能心无凝滞地快速走出。</p><p>这一爻有具体的生命印证：左手骨折、生活受挫的低谷期，正是一次「升虚邑」——理解处境的结构之后，「怀疑」这个念头根本没有空间冒出来。</p><blockquote><p>不疑不是练出来的定力，是路走对了之后，自然没有岔路可犹豫。</p></blockquote><h3 id="六四-·-王用亨于岐山-吉-无咎" tabindex="-1">六四 · 王用亨于岐山，吉，无咎 <a class="header-anchor" href="#六四-·-王用亨于岐山-吉-无咎" aria-label="Permalink to &quot;六四 · 王用亨于岐山，吉，无咎&quot;">​</a></h3><ul><li>阴爻居四位，正式踏入上卦「坤」（地）的场域</li><li><strong>王用亨于岐山</strong>：周文王在岐山郑重祭祀</li><li>小象「顺事也」</li></ul><p>这是一个转折：从「独自耕耘」向「与更大的系统对齐」的跨越。顺事——不是靠力量夺取，而是用郑重、合乎法度的方式去对齐天命与大局。</p><p>判断标准不是祭品是否丰盛，而是「顺事」的姿态：先找准真正该献上去的核心，再郑重献上，而不是临时凑数。</p><blockquote><p>郑重的姿态本身，就是与大局对齐的入场券。</p></blockquote><h3 id="六五-·-贞吉-升阶" tabindex="-1">六五 · 贞吉，升阶 <a class="header-anchor" href="#六五-·-贞吉-升阶" aria-label="Permalink to &quot;六五 · 贞吉，升阶&quot;">​</a></h3><ul><li>阴爻居五位（阳位）——本该刚健主动的位置，坐的却是柔顺谦冲的性质</li><li>而这正是「大得志」的关键；小象「大得志也」</li></ul><p>这里有一个关键反转：<strong>不是「做到了这些才得志」，而是「正因为有志（初心），才能一路以巽的方式顺行到坤；来到更广阔的大地之后，依然保持柔与顺，遂而大得志」。</strong></p><p>「志」不是终点，是从初六到六五贯穿始终、从未走丢的东西。</p><blockquote><p>柔不是没有志，是有志而不必用力。</p></blockquote><h3 id="上六-·-冥升-利于不息之贞" tabindex="-1">上六 · 冥升，利于不息之贞 <a class="header-anchor" href="#上六-·-冥升-利于不息之贞" aria-label="Permalink to &quot;上六 · 冥升，利于不息之贞&quot;">​</a></h3><ul><li>卦之极致，升至昏暗不明之处</li><li>小象「消不富也」——升到极致已是消耗，而非丰盈</li></ul><p>升没有一个「到顶了、可以歇了」的终点；极致处反而看不清方向，还在消耗。唯一的支撑是「不息之贞」——不是想通了什么大道理，是持续做下去的动作本身。</p><blockquote><p>看不清方向的时候，守正就是方向。</p></blockquote><h2 id="【原典层】字词释义" tabindex="-1">【原典层】字词释义 <a class="header-anchor" href="#【原典层】字词释义" aria-label="Permalink to &quot;【原典层】字词释义&quot;">​</a></h2>',32)),i(d,{title:"字词释义",items:[{term:"升",pinyin:["shēng"],meaning:"上升、登高。卦体坤上巽下，木在地中生长，喻积小成高大。"},{term:"孚",pinyin:["fú"],meaning:"诚信、信实，指内核的真实。九二「孚乃利用禴」：内核真实，形式可简。"},{term:"禴",pinyin:["yuè"],meaning:"薄祭、夏祭。祭礼从简而心诚为先。"},{term:"允升",pinyin:["yǔn","shēng"],meaning:"允即信从、诚然。为众人所信从而上升，故大吉。"},{term:"虚邑",pinyin:["xū","yì"],meaning:"空城、无人防守的城邑，喻路径通畅无阻。"},{term:"亨",pinyin:["hēng"],meaning:"此处通「享」，指祭祀献享。六四「王用亨于岐山」。"},{term:"岐山",pinyin:["qí","shān"],meaning:"周室发祥之地，文王在此祭天，喻与更大的系统对齐。"},{term:"升阶",pinyin:["shēng","jiē"],meaning:"踏阶而上，一级一级稳步登临。六五「贞吉，升阶」。"},{term:"冥升",pinyin:["míng","shēng"],meaning:"升至昏暗不明之处。象传「消不富也」：是消耗，不是丰盈。"},{term:"不息之贞",pinyin:["bù","xī","zhī","zhēn"],meaning:"持续不断的守正。不是想通了大道理，是继续做下去的动作本身。"},{term:"顺德",pinyin:["shùn","dé"],meaning:"顺其德、顺时顺势之德。象传「君子以顺德」，是升卦的总纲。"},{term:"柔以时升",pinyin:["róu","yǐ","shí","shēng"],meaning:"彖传语。以柔顺应时势而升，不是硬冲——升卦全篇的底色。"},{term:"南征",pinyin:["nán","zhēng"],meaning:"向南进发。离为南、为明，喻向光明处前行；彖传「志行也」。"}]}),t[2]||(t[2]=a('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一卦在说什么" tabindex="-1">象：这一卦在说什么 <a class="header-anchor" href="#象-这一卦在说什么" aria-label="Permalink to &quot;象：这一卦在说什么&quot;">​</a></h3><p>升卦讲的是<strong>顺着长上去</strong>。坤上巽下，木在地中生长，日渐破土——所以卦辞说「元亨，用见大人，勿恤，南征吉」：大为亨通，可以见大人，不必忧虑，向南前行吉。</p><p>彖传把它的机制说得很清楚：「柔以时升，巽而顺，刚中而应，是以大亨。」升的动力不是蛮力，是柔、是时、是顺、是内刚而外应。</p><h3 id="理-为什么这一卦重要" tabindex="-1">理：为什么这一卦重要 <a class="header-anchor" href="#理-为什么这一卦重要" aria-label="Permalink to &quot;理：为什么这一卦重要&quot;">​</a></h3><p>因为它纠正一个默认反应：把「升」理解成往上冲。</p><p>升的本质不是「用力往上冲」，而是「顺着该顺的势，一层一层地长上去」。由此，「积」也就有了正解——积不是功利手段，是顺势走出来的自然痕迹；水往低处走、江海自然汇聚，那才是积。</p><p>这一卦还留下三个需要反复核对的分辨（详见「我的理解」）：<strong>积小</strong>是顺德走出来的痕迹，还是拖延的遮羞布；<strong>孚与禴</strong>是内核真实而形式可简，还是用简陋掩盖不敢深耕；<strong>鼓舞与理解</strong>是看清结构后恐惧自然松开，还是靠情绪打气、力气用尽即塌。</p><h3 id="用-今天如何应用" tabindex="-1">用：今天如何应用 <a class="header-anchor" href="#用-今天如何应用" aria-label="Permalink to &quot;用：今天如何应用&quot;">​</a></h3><ol><li><strong>先找同盟</strong>：升的起点是与志同道合者合志，而不是孤身硬扛（初六）</li><li><strong>守住内核</strong>：起步阶段不必用隆重成果交换认可，但也不要用简陋掩盖焦虑（九二）</li><li><strong>专注到无隙犹豫</strong>：路径通畅时不去反复怀疑，是理解结构之后的结果（九三）</li><li><strong>以「顺事」的姿态对齐大局</strong>：先找准真正该献上的核心，再郑重献上（六四）</li><li><strong>有志而不必用力</strong>：保持柔顺谦冲，是「大得志」的形态，不是它的代价（六五）</li><li><strong>为看不清的阶段设计机制</strong>：升到暗处仍在消耗，此时需要一套「哪怕看不清也能持续」的最小行动（上六）</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>升卦的完整地图：</p><table tabindex="0"><thead><tr><th>爻位</th><th>爻辞要点</th><th>功课</th><th>关键词</th></tr></thead><tbody><tr><td>卦辞</td><td>元亨，用见大人，勿恤，南征吉</td><td>柔以时升，顺事而行</td><td>积小以高大</td></tr><tr><td>初六</td><td>允升，大吉</td><td>找志同道合的同盟</td><td>上合志也，不孤行</td></tr><tr><td>九二</td><td>孚乃利用禴，无咎</td><td>内核真实，形式可简</td><td>排场给别人，孚给自己</td></tr><tr><td>九三</td><td>升虚邑</td><td>专注到没有空间犹豫</td><td>无所疑也，路径通畅</td></tr><tr><td>六四</td><td>王用亨于岐山，吉无咎</td><td>郑重地与更大系统对齐</td><td>顺事，先找核心</td></tr><tr><td>六五</td><td>贞吉，升阶</td><td>柔顺谦冲而大得志</td><td>有志而不必用力</td></tr><tr><td>上六</td><td>冥升，利于不息之贞</td><td>在暗处持续做下去</td><td>不息之贞</td></tr></tbody></table><p>核心洞见：</p><ol><li><strong>柔以时升</strong>——升的动力不是蛮力，是该长的时候长、该顺的时候顺</li><li><strong>积小不是堆高，是长高</strong>——积是顺势走出来的痕迹，不是刻意堆砌的表演</li><li><strong>排场是给别人看的，孚是给自己留的底</strong>——起步阶段不必用隆重成果交换认可，真实的内核足以撑起一切不完整</li><li><strong>无所疑不是克制，是专注</strong>——理解处境结构之后，怀疑这个念头根本没有空间冒出来</li><li><strong>顺事是入场券</strong>——不是靠力量夺取，而是以郑重、合乎法度的方式与大局对齐</li><li><strong>志不是终点</strong>——「正因为有志，才能一路以巽的方式顺行到坤」，柔与顺是有志者的形态</li><li><strong>上六没有终点</strong>——升到极致反而看不清方向、还在消耗，唯一的支撑是不停地守正</li></ol><p>锚点金句：<strong>盥而不荐是现在，孚乃利用禴是将来——不必等排场，但也不必急着端。</strong></p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p>学这一卦，起点是一次真实的低谷：左手骨折，生活受挫，一度近乎绝望。触发好奇的契机是「祸福相倚、塞翁失马」这类老话，但真正让我继续下去的不是励志——<strong>不是被「天行健，地势坤」「盥而不荐」「城复于隍」这些卦辞鼓舞，而是理解</strong>：把自己的处境代入进去，发现处境本身有一个更大的结构在托着它。</p><blockquote><p>励志是往身上加一点力气，理解是把脚下的地图打开。</p></blockquote><p>随着一卦一卦地学，我找到了方向，从此能「不怀疑」地继续——这正对应九三的「无所疑也」。它落到了当下：<strong>Dao-is-Coding</strong>，本质是想把当年这副「理解处境结构的眼镜」，做成一套可以传给别人的方法。</p><p>三个值得反复核对的分辨：</p><table tabindex="0"><thead><tr><th>分辨对象</th><th>前者（清醒 / 真实）</th><th>后者（需警惕）</th></tr></thead><tbody><tr><td>积小</td><td>顺德走出来的痕迹</td><td>拖延的遮羞布</td></tr><tr><td>孚与禴</td><td>内核真实，形式可简</td><td>用简陋掩盖不敢深耕</td></tr><tr><td>鼓舞与理解</td><td>看清结构，恐惧自然松开</td><td>靠情绪打气，力气用尽即塌</td></tr></tbody></table><p>一句话收束：<strong>升，不是一路凯歌，而是「哪怕升到看不清方向，依然没有停下守正」的持续动作。</strong></p><p>后续可深化的方向：</p><ol><li>六四「顺事」的持续实践：内容精炼度与传播效率之间的动态平衡</li><li>九二「孚」的具体校验方式：如何在快速产出中，持续自查「内核是否真实」而非「形式是否够用」</li><li>上六「不息之贞」的落地：当项目进入看不清方向的阶段时，如何设计一套「哪怕看不清也能持续」的最小行动机制</li></ol><p>（本篇整理自与易师关于升卦的对谈，核心目的是把卦象逻辑与 Dao-is-Coding 的路径、以及自己的心理盲点对齐，供后续回看与体系化沉淀。）</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>相关卦象：<a href="/Dao/yijing/hexagrams/45-zedicui">萃（第四十五卦）</a>、<a href="/Dao/yijing/hexagrams/47-zeshukun">困（第四十七卦）</a>、<a href="/Dao/yijing/hexagrams/20-fengdiguan">观（第二十卦）</a>、<a href="/Dao/yijing/hexagrams/11-ditiantai">泰（第十一卦）</a></li><li>序卦：<strong>「聚而上者谓之升」</strong>——萃是聚，升是聚而上升；升之后是困，「升而不已必困」，故升卦的功课里既有「柔以时」，也有「不息之贞」</li><li>观卦「盥而不荐」与升卦九二「孚乃利用禴」相呼应：<strong>盥而不荐是现在，孚乃利用禴是将来</strong>——不必等排场，但也不必急着端</li></ul>',28))])}}});export{b as __pageData,x as default};
